import '../../../core/network/api_client.dart';class AlertItem{AlertItem.fromJson(Map<String,dynamic>j):id=j['id'] as String,message=j['message'] as String,severity=j['severity'].toString(),read=j['isRead'] as bool,createdAt=DateTime.parse(j['createdAt'] as String).toLocal();final String id,message,severity;final bool read;final DateTime createdAt;}class AlertRepository{AlertRepository(this._client);final ApiClient _client;Future<List<AlertItem>>all()async{final r=await _client.dio.get<List<dynamic>>('/api/alerts');return r.data!.map((e)=>AlertItem.fromJson(e)).toList();}Future<void>read(String id)=>_client.dio.post<void>('/api/alerts/'+id+'/read');}